#!/usr/bin/env node
// Query helper for call-graph.json files (generated by the nightly digest pipeline).
// Lets an agent look up call relationships without reading the whole JSON file.
// Zero dependencies, Node 18+.
//
// Usage: node .github/scripts/cg.js <command> [args] [options]
//
//   find <text>            Search methods by FQN substring (case-insensitive)
//   callees <method>       Methods called by <method>
//   callers <method>       Methods that call <method>
//   path <from> <to>       Shortest call path from <from> to <to>
//
// Options:
//   --depth N              callees/callers: follow edges N levels (default 1)
//   --category C           find: only this class category (usecase, controller, ...)
//   --limit N              find: max results (default 30)
//   --desc                 also print each method's one-line description
//   --app NAME             monorepo: only the graph of apps/NAME
//   --file PATH            use exactly this call-graph.json
//
// Which graphs are read (unless --file is given):
//   * apps/*/docs/call-graph.json  - monorepo, one graph per app. Results are labeled
//                                    "[app]". The root docs/call-graph.json is ignored
//                                    here: monorepos keep a stale legacy copy of it.
//   * docs/call-graph.json         - single-service repo.
//
// <method> is an FQN as stored in call-graph.json, e.g. "CommandHandler.execute(Command)",
// or any unique substring of one, e.g. "CommandHandler.execute(". Ambiguous input
// prints the candidates and exits with code 2.

const fs = require("fs");
const path = require("path");

const USAGE = "Usage: node cg.js <find|callees|callers|path> <args> [--depth N] [--category C] [--limit N] [--desc] [--app NAME] [--file PATH]";

function parseArgs(argv) {
  const opts = { depth: 1, limit: 30, desc: false, category: null, file: null, app: null };
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--desc") opts.desc = true;
    else if (a === "--depth") opts.depth = Number(argv[++i]);
    else if (a === "--limit") opts.limit = Number(argv[++i]);
    else if (a === "--category") opts.category = argv[++i];
    else if (a === "--file") opts.file = argv[++i];
    else if (a === "--app") opts.app = argv[++i];
    else positional.push(a);
  }
  if (!Number.isInteger(opts.depth) || opts.depth < 1) fail("--depth must be a positive integer");
  if (!Number.isInteger(opts.limit) || opts.limit < 1) fail("--limit must be a positive integer");
  return { cmd: positional[0], args: positional.slice(1), opts };
}

function fail(msg, code = 1) {
  console.error(msg);
  process.exit(code);
}

function readGraph(file, app) {
  let graph;
  try {
    graph = JSON.parse(fs.readFileSync(file, "utf8"));
  } catch (e) {
    fail(`${file} is not valid JSON (${e.message}); it may be truncated, so regenerate it or pass another copy with --file`);
  }
  const methods = graph.method_index;
  if (!methods || typeof methods !== "object") fail(`no method_index in ${file}`);
  const callers = new Map();
  for (const [fqn, m] of Object.entries(methods)) {
    for (const callee of m.calls || []) {
      if (!callers.has(callee)) callers.set(callee, []);
      callers.get(callee).push(fqn);
    }
  }
  return { app, methods, callers };
}

// Returns the list of graphs to query: [{ app, methods, callers }].
function load(opts) {
  if (opts.file) {
    if (!fs.existsSync(opts.file)) fail(`call-graph.json not found: ${opts.file}`);
    return [readGraph(opts.file, null)];
  }

  const appsDir = path.join("apps");
  const appGraphs = [];
  if (fs.existsSync(appsDir)) {
    for (const name of fs.readdirSync(appsDir).sort()) {
      const file = path.join(appsDir, name, "docs", "call-graph.json");
      if (fs.existsSync(file)) appGraphs.push({ app: name, file });
    }
  }

  if (appGraphs.length > 0) {
    let selected = appGraphs;
    if (opts.app) {
      selected = appGraphs.filter((g) => g.app === opts.app);
      if (selected.length === 0) {
        fail(`no app "${opts.app}"; available: ${appGraphs.map((g) => g.app).join(", ")}`);
      }
    }
    return selected.map((g) => readGraph(g.file, g.app));
  }

  if (opts.app) fail(`--app needs a monorepo with apps/*/docs/call-graph.json; none found`);
  const target = path.join("docs", "call-graph.json");
  if (!fs.existsSync(target)) fail(`call-graph.json not found: ${target} (use --file)`);
  return [readGraph(target, null)];
}

// A match is { g: graph, fqn }.
function resolve(graphs, query) {
  const exact = graphs.filter((g) => g.methods[query]).map((g) => ({ g, fqn: query }));
  if (exact.length === 1) return exact[0];

  let hits = exact;
  if (exact.length === 0) {
    const q = query.toLowerCase();
    hits = graphs.flatMap((g) =>
      Object.keys(g.methods).filter((k) => k.toLowerCase().includes(q)).map((fqn) => ({ g, fqn })),
    );
    if (hits.length === 1) return hits[0];
  }

  const showApp = graphs.length > 1;
  if (hits.length === 0) fail(`no method matches "${query}" (try: find ${query.split(/[.(]/)[0]})`);
  console.error(`"${query}" is ambiguous (${hits.length} matches${showApp ? "; narrow with --app" : ""}):`);
  for (const h of hits.slice(0, 20)) console.error(`  ${tag(h.g, showApp)}${h.fqn}`);
  if (hits.length > 20) console.error(`  ... ${hits.length - 20} more`);
  process.exit(2);
}

function tag(g, showApp) {
  return showApp && g.app ? `[${g.app}] ` : "";
}

function label(g, fqn, withDesc, showApp) {
  const m = g.methods[fqn];
  if (!m) return `${tag(g, showApp)}${fqn}  [not in index]`;
  let s = `${tag(g, showApp)}${fqn}  [${m.category}]  ${m.file_path}`;
  if (withDesc && m.description) s += `\n      ${m.description}`;
  return s;
}

// Breadth-first walk over `edges(fqn) -> fqn[]`, printing one indented line per newly visited node.
function walk(g, start, edges, depth, withDesc) {
  const seen = new Set([start]);
  let frontier = [start];
  let count = 0;
  for (let level = 1; level <= depth && frontier.length; level++) {
    const next = [];
    for (const from of frontier) {
      for (const to of edges(from)) {
        if (seen.has(to)) continue;
        seen.add(to);
        next.push(to);
        count++;
        console.log(`${"  ".repeat(level - 1)}${label(g, to, withDesc, false)}`);
      }
    }
    frontier = next;
  }
  if (count === 0) console.log("(none)");
}

function shortestPath(g, from, to) {
  const prev = new Map([[from, null]]);
  const queue = [from];
  while (queue.length) {
    const cur = queue.shift();
    if (cur === to) break;
    for (const n of (g.methods[cur] && g.methods[cur].calls) || []) {
      if (prev.has(n)) continue;
      prev.set(n, cur);
      queue.push(n);
    }
  }
  if (!prev.has(to)) return null;
  const chain = [];
  for (let n = to; n !== null; n = prev.get(n)) chain.unshift(n);
  return chain;
}

function main() {
  const { cmd, args, opts } = parseArgs(process.argv.slice(2));
  if (!cmd) fail(USAGE);
  const graphs = load(opts);
  const showApp = graphs.length > 1;

  switch (cmd) {
    case "find": {
      if (!args[0]) fail("find needs a search text");
      const q = args[0].toLowerCase();
      const hits = graphs.flatMap((g) =>
        Object.keys(g.methods)
          .filter((k) => (!opts.category || g.methods[k].category === opts.category) && k.toLowerCase().includes(q))
          .map((fqn) => ({ g, fqn })),
      );
      for (const h of hits.slice(0, opts.limit)) console.log(label(h.g, h.fqn, opts.desc, showApp));
      if (hits.length > opts.limit) console.log(`... ${hits.length - opts.limit} more (raise --limit or narrow the text)`);
      if (hits.length === 0) console.log("(none)");
      break;
    }
    case "callees": {
      if (!args[0]) fail("callees needs a method");
      const { g, fqn } = resolve(graphs, args[0]);
      console.log(`callees of ${tag(g, showApp)}${fqn}`);
      walk(g, fqn, (f) => (g.methods[f] && g.methods[f].calls) || [], opts.depth, opts.desc);
      break;
    }
    case "callers": {
      if (!args[0]) fail("callers needs a method");
      const { g, fqn } = resolve(graphs, args[0]);
      console.log(`callers of ${tag(g, showApp)}${fqn}`);
      walk(g, fqn, (f) => g.callers.get(f) || [], opts.depth, opts.desc);
      break;
    }
    case "path": {
      if (!args[0] || !args[1]) fail("path needs <from> <to>");
      const from = resolve(graphs, args[0]);
      const to = resolve(graphs, args[1]);
      if (from.g !== to.g) {
        console.log(`no call path: ${tag(from.g, true)}${from.fqn} and ${tag(to.g, true)}${to.fqn} are in different apps`);
        break;
      }
      const chain = shortestPath(from.g, from.fqn, to.fqn);
      if (!chain) {
        console.log(`no call path from ${from.fqn} to ${to.fqn}`);
        break;
      }
      chain.forEach((n, i) => console.log(`${"  ".repeat(i)}${label(from.g, n, opts.desc, false)}`));
      break;
    }
    default:
      fail(`unknown command "${cmd}"\n${USAGE}`);
  }
}

main();
